function friendly(e) {
  const s = e.status || 0, body = (e.body || "").toLowerCase();
  if (body.includes("credit balance")) return { code: "NO_CREDIT", error: "Everywhere's AI account has run out of credit. The owner needs to top it up." };
  if (s === 429 || body.includes("quota") || body.includes("resource_exhausted") || body.includes("rate_limit"))
    return { code: "AI_LIMIT", error: "Everywhere is busy: the AI usage limit was reached. Try again in a minute." };
  if (s === 400 && (body.includes("api key") || body.includes("api_key")))
    return { code: "KEY_INVALID", error: "The site's AI key was refused. The owner needs to check the key secret." };
  if (s === 401 || s === 403) return { code: "KEY_REFUSED_" + s, error: "The AI provider refused the site's key or model. The owner needs to check the key and model." };
  if (s === 400 && /too long|too many tokens|context length|context window|exceeds|input token/.test(body))
    return { code: "TOO_LONG_FOR_MODEL", error: "That text is too long for the AI model this site uses. Try a shorter part." };
  if (s === 400 && /image/.test(body)) return { code: "IMAGE_REFUSED", error: "The AI model couldn't read that image. Try a JPEG or PNG, or a model that supports images." };
  if (s === 413) return { code: "TOO_LONG_FOR_MODEL", error: "That text is too long for the AI model this site uses. Try a shorter part." };
  if (s === 504) return { code: "AI_TIMEOUT", error: "The AI took too long to answer. Try again, or ask a shorter question." };
  if (s === 404) return { code: "MODEL_NOT_FOUND", error: "The AI model isn't available. The owner needs to choose another model." };
  if (s >= 500) return { code: "AI_DOWN_" + s, error: "The AI service had a problem or is overloaded. Try again in a minute." };
  if (s) return { code: "AI_" + s, error: "The AI could not answer this message." };
  return { code: "SERVER_ERROR", error: "Everywhere hit an unexpected problem. Try again." };
}
function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }
  });
}

async function handleChat(request, env) {
  if (request.method !== "POST") return json({ code: "METHOD", error: "Use POST." }, 405);
  const provider = providerFor(env);
  const key = keyFor(env, provider);
  if (!key) return json({ code: "NO_KEY", error: "Everywhere isn't connected yet: the owner must add the AI key secret." }, 503);
  const ip = request.headers.get("CF-Connecting-IP") || "unknown";
  if (limited(ip)) return json({ code: "TOO_MANY", error: "You've sent a lot of messages. Wait a few minutes, then continue." }, 429);
  let body;
  try { body = await request.json(); } catch { return json({ code: "BAD_REQUEST", error: "That message couldn't be read." }, 400); }
  const maxInput = Number(env.MAX_INPUT_CHARS) > 0 ? Number(env.MAX_INPUT_CHARS) : MAX_INPUT;
  const raw = (Array.isArray(body.messages) ? body.messages : [])
    .filter((m) => (m.role === "user" || m.role === "assistant") && typeof m.content === "string" && m.content.trim())
    .slice(-MAX_TURNS);
  const last = raw.length ? raw[raw.length - 1].content.length : 0;
  if (last > maxInput) return json({ code: "TOO_LONG", error: "That text is too long: about " + Math.round(last / 6e3) + " thousand words. The limit is about " + Math.round(maxInput / 6e3) + " thousand words. Try a shorter part." }, 413);
  const msgs = fitBudget(raw, maxInput);
  const lastRaw = raw.length ? raw[raw.length - 1] : {};
  const rawImgs = Array.isArray(lastRaw.images) ? lastRaw.images : [];
  if (rawImgs.length > MAX_IMAGES) return json({ code: "TOO_MANY_IMAGES", error: "At most " + MAX_IMAGES + " images per message." }, 413);
  let imgBytes = 0;
  for (const x of rawImgs) {
    const bad = !x || typeof x.data !== "string" || typeof x.type !== "string" ? "malformed" : sniffImage(x.type, x.data);
    if (bad) return json({ code: "BAD_IMAGE", error: "One of the images was refused (" + bad + "). Attach it again from the paperclip." }, 415);
    imgBytes += x.data.length;
  }
  if (imgBytes > MAX_IMAGE_B64) return json({ code: "IMAGES_TOO_BIG", error: "The images are too large together. Attach fewer, or smaller, images." }, 413);
  const imgs = rawImgs.map((x) => ({ type: x.type, data: x.data }));
  const total = msgs.reduce((n, m) => n + m.content.length, 0);
  const deadline = Date.now() + (total > LONG_AT || imgs.length ? 170e3 : 55e3);
  if (total > LONG_AT && limited(ip, longHits, LONG_LIMIT)) return json({ code: "TOO_MANY_LONG", error: "Long texts are limited to " + LONG_LIMIT.perIp + " messages an hour per visitor, to keep the site affordable. Short questions still work." }, 429);
  while (msgs.length && msgs[0].role !== "user") msgs.shift();
  if (!msgs.length || msgs[msgs.length - 1].role !== "user") return json({ code: "EMPTY", error: "Write a message first." }, 400);
  const mode = MODES[body.mode] !== void 0 ? body.mode : "chat";
  const model = provider === "claude" ? env.MODEL_ID || CLAUDE_DEFAULT : await pickModel(key, env);
  const base = baseFor(model);
  const rules = RULES.split("{{BASE}}").join(base) + (MODES[mode] ? "\n\n" + MODES[mode] : "");
  const examples = EXAMPLES.map((m) => ({ role: m.role, content: m.content.split("{{BASE}}").join(base) }));
  try {
    let reply;
    if (provider === "claude") {
      reply = await callClaude(key, model, rules, [...examples, ...msgs], deadline, imgs);
    } else {
      try {
        reply = await callModel(key, model, [{ role: "system", content: rules }, ...examples, ...addImages(msgs, imgs, "gemini")], deadline);
      } catch (e) {
        const b = (e.body || "").toLowerCase();
        if (e.status !== 400 || !(b.includes("instruction") || b.includes("system"))) throw e;
        reply = await callModel(key, model, [
          { role: "user", content: "INSTRUCTIONS (follow them always):\n" + rules },
          { role: "assistant", content: "Understood." },
          ...examples,
          ...addImages(msgs, imgs, "gemini")
        ], deadline);
      }
    }
    if (!reply) return json({ code: "EMPTY_REPLY", error: "The AI sent back an empty answer. Try again." }, 502);
    return json({ reply, model });
  } catch (e) {
    console.error("Everywhere chat error", model, e.status || "", e.body || String(e));
    return json(friendly(e), 502);
  }
}

async function handleStatus(env) {
  const provider = providerFor(env);
  const key = keyFor(env, provider);
  if (!key) return json({ ok: false, provider, keyPresent: false, note: provider === "claude" ? "Add the ANTHROPIC_API_KEY secret in Cloudflare." : "Add the GEMINI_API_KEY secret in Cloudflare." });
  try {
    if (provider === "claude") {
      const ids = await listClaudeModels(key);
      const model = env.MODEL_ID || CLAUDE_DEFAULT;
      return json({ ok: true, provider, keyPresent: true, model, modelAvailable: ids.includes(model), modelsSeen: ids.length });
    }
    const ids = await listModels(key);
    const model = await pickModel(key, env);
    return json({ ok: true, provider, keyPresent: true, model, modelAvailable: ids.includes(model), modelsSeen: ids.length });
  } catch (e) {
    console.error("Everywhere status error", e.status || "", e.body || String(e));
    return json({ ok: false, keyPresent: true, ...friendly(e), googleStatus: e.status || null });
  }
}

