var CSP = "default-src 'self'; script-src 'self' 'sha256-qOhFsq0QMV2REqNwk5hGH5bZE9SkX6gt6yeyKdYPv+U='; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https://i.ytimg.com; font-src 'self'; frame-src https://www.youtube-nocookie.com; connect-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'self' https://dash.cloudflare.com https://*.cloudflare.com https://*.cloudflarepreviews.com";

var SECURITY = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()"
  // Framing is controlled by CSP frame-ancestors (only Cloudflare's preview may frame the site).
};

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
var DECODED = {};

function page(html, origin, status = 200, head = false) {
  return new Response(head ? null : html.split("{{ORIGIN}}").join(origin), {
    status,
    headers: {
      ...SECURITY,
      "Content-Type": "text/html; charset=utf-8",
      "Content-Security-Policy": CSP,
      "Cache-Control": "no-cache"
    }
  });
}

function serveAsset(path, head) {
  const a = ASSETS[path];
  if (!a) return null;
  if (a.b64 && !DECODED[path]) DECODED[path] = b64ToBytes(a.body);
  return new Response(head ? null : (a.b64 ? DECODED[path] : a.body), {
    headers: { ...SECURITY, "Content-Type": a.type, "Cache-Control": a.cache, "Access-Control-Allow-Origin": "*" }
  });
}

export { sniffImage, fitBudget, withCache, addImages, alternate, friendly };
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const origin = url.origin;
    let path = url.pathname;

    if (path === "/api/chat") return handleChat(request, env);
    if (path === "/api/status" && request.method === "GET") return handleStatus(env);
    if (path.startsWith("/api/")) return json({ code: "NOT_FOUND", error: "Unknown API route." }, 404);

    const head = request.method === "HEAD";
    if (request.method !== "GET" && !head) return new Response("Method not allowed", { status: 405, headers: { Allow: "GET, HEAD" } });

    if (path === "/robots.txt") {
      return new Response(head ? null : "User-agent: *\nAllow: /\nDisallow: /api/\nSitemap: " + origin + "/sitemap.xml\n", { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "public, max-age=86400" } });
    }
    if (path === "/sitemap.xml") {
      const xml = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
        SITEMAP.map((p) => "  <url><loc>" + origin + p + "</loc></url>").join("\n") + "\n</urlset>\n";
      return new Response(head ? null : xml, { headers: { "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "public, max-age=86400" } });
    }

    const asset = serveAsset(path, head);
    if (asset) return asset;

    if (path === "/index.html") return Response.redirect(origin + "/", 301);
    if (path.length > 1 && path.endsWith("/")) return Response.redirect(origin + path.slice(0, -1) + url.search, 301);
    if (path === "/chat") return Response.redirect(origin + "/ask" + url.search, 301);

    if (PAGES[path] && path !== "/404") return page(PAGES[path], origin, 200, head);
    return page(PAGES["/404"], origin, 404, head);
  }
};
